import { IngestPipeline, MaterializedView, OlapTable, Key, sql } from "@514labs/moose-lib";

// Product interaction events: views, add-to-carts, purchases
export interface ProductEvent {
  id: Key<string>;
  user_id: string;
  product_id: string;
  event_type: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  properties: any; // JSONB column with price and other metadata
}

// Create the main table for product events
export const ProductEventTable = new OlapTable<ProductEvent>("ProductEvent", {
  orderByFields: ["user_id", "timestamp"] // Optimize for user-based queries
});

// Create an ingestion pipeline for product events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: true, // Let pipeline create its own table
  stream: true,
  ingestApi: true,
});

// Interface for top products aggregation
export interface TopProduct {
  product_id: string;
  purchase_count: number;
  total_revenue: number;
}

// Interface for conversion funnel aggregation
export interface ConversionFunnel {
  product_id: string;
  views: number;
  add_to_carts: number;
  purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

// Interface for hourly activity aggregation
export interface HourlyActivity {
  hour: Date;
  event_type: string;
  event_count: number;
}

// Materialized view for top products by purchase count with revenue
export const TopProductsView = new MaterializedView<TopProduct>({
  selectStatement: sql.statement`
    SELECT
      product_id,
      count(*) as purchase_count,
      sum(JSONExtractFloat(properties, 'price')) as total_revenue
    FROM ${ProductEventTable}
    WHERE event_type = 'purchase'
    GROUP BY product_id
    ORDER BY purchase_count DESC
  `,
  selectTables: [ProductEventTable],
  tableName: "ProductEvent",
  materializedViewName: "top_products"
});

// Materialized view for conversion funnel
export const ConversionFunnelView = new MaterializedView<ConversionFunnel>({
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'add_to_cart') as add_to_carts,
      countIf(event_type = 'purchase') as purchases,
      if(views > 0, add_to_carts / views * 100, 0) as view_to_cart_rate,
      if(add_to_carts > 0, purchases / add_to_carts * 100, 0) as cart_to_purchase_rate,
      if(views > 0, purchases / views * 100, 0) as overall_conversion_rate
    FROM ${ProductEventTable}
    GROUP BY product_id
    HAVING views > 0
  `,
  selectTables: [ProductEventTable],
  tableName: "ProductEvent",
  materializedViewName: "conversion_funnel"
});

// Materialized view for hourly activity breakdown
export const HourlyActivityView = new MaterializedView<HourlyActivity>({
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(timestamp) as hour,
      event_type,
      count(*) as event_count
    FROM ${ProductEventTable}
    GROUP BY hour, event_type
    ORDER BY hour DESC, event_type
  `,
  selectTables: [ProductEventTable],
  tableName: "ProductEvent",
  materializedViewName: "hourly_activity"
});

