          console.log(`✓ Sent event ${event.id} (${event.event_type}) for product ${event.product_id}`);
          resolve(body);
        } else {
          console.error(`✗ Failed to send event ${event.id}: ${res.statusCode} ${body}`);
          reject(new Error(`HTTP ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error(`✗ Error sending event ${event.id}:`, err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function extractAndLoad() {
  console.log('Starting Postgres extraction and loading to Moose...');
  console.log(`Total events to process: ${mockEvents.length}`);

  let successCount = 0;
  let failureCount = 0;

  for (const event of mockEvents) {
    try {
      await sendEventToMoose(event);
      successCount++;
      // Small delay to avoid overwhelming the API
      await new Promise(resolve => setTimeout(resolve, 100));
    } catch (error) {
      failureCount++;
      console.error(`Failed to send event ${event.id}:`, error.message);
    }
  }

  console.log('\n📊 Extraction Summary:');
  console.log(`✓ Successfully sent: ${successCount} events`);
  console.log(`✗ Failed: ${failureCount} events`);
  console.log(`📈 Total processed: ${successCount + failureCount} events`);
}

// Fix the http import
const http = require('http');

// Run the extraction
extractAndLoad().catch(console.error);

