const express = require('express');
const cors = require('cors');

const app = express();
const PORT = 3000;

// Middleware
app.use(express.json());
app.use(cors());

// In-memory data store (replacing ClickHouse for this demo)
let productEvents = [];

// Data Models (equivalent to Moose interfaces)
function validateProductEvent(event) {
  const requiredFields = ['id', 'user_id', 'product_id', 'event_type', 'timestamp'];
  const validEventTypes = ['view', 'add_to_cart', 'purchase'];

  for (const field of requiredFields) {
    if (!event[field]) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  if (!validEventTypes.includes(event.event_type)) {
    throw new Error(`Invalid event_type: ${event.event_type}`);
  }

  // Ensure timestamp is a Date object
  event.timestamp = new Date(event.timestamp);

  // Ensure properties is an object
  event.properties = event.properties || {};

  return event;
}

// INGESTION ENDPOINT (equivalent to Moose ingestion API)
app.post('/ingest/ProductEvent', (req, res) => {
  try {
    const event = validateProductEvent(req.body);
    productEvents.push(event);

    console.log(`✓ Ingested event ${event.id} (${event.event_type}) for product ${event.product_id}`);
    res.status(200).json({ success: true, message: 'Event ingested successfully' });
  } catch (error) {
    console.error(`✗ Failed to ingest event: ${error.message}`);
    res.status(400).json({ success: false, error: error.message });
  }
});

// AGGREGATION FUNCTIONS (equivalent to Moose MaterializedViews)

function getTopProducts() {
  // Aggregate purchase events by product_id
  const purchaseEvents = productEvents.filter(e => e.event_type === 'purchase');
  const productStats = {};

  for (const event of purchaseEvents) {
    if (!productStats[event.product_id]) {
      productStats[event.product_id] = {
        product_id: event.product_id,
        purchase_count: 0,
        total_revenue: 0
      };
    }

    productStats[event.product_id].purchase_count++;

    // Extract price from properties
    const price = event.properties.price || 0;
    productStats[event.product_id].total_revenue += price;
  }

  // Sort by purchase count descending
  return Object.values(productStats)
    .sort((a, b) => b.purchase_count - a.purchase_count);
}

function getConversionFunnel() {
  // Aggregate all events by product_id to calculate funnel metrics
  const productStats = {};

  for (const event of productEvents) {
    if (!productStats[event.product_id]) {
      productStats[event.product_id] = {
        product_id: event.product_id,
        views: 0,
        add_to_carts: 0,
        purchases: 0
      };
    }

    switch (event.event_type) {
      case 'view':
        productStats[event.product_id].views++;
        break;
      case 'add_to_cart':
        productStats[event.product_id].add_to_carts++;
        break;
      case 'purchase':
        productStats[event.product_id].purchases++;
        break;
    }
  }

  // Calculate conversion rates
  return Object.values(productStats)
    .map(stats => ({
      ...stats,
      view_to_cart_rate: stats.views > 0 ? (stats.add_to_carts / stats.views * 100) : 0,
      cart_to_purchase_rate: stats.add_to_carts > 0 ? (stats.purchases / stats.add_to_carts * 100) : 0,
      overall_conversion_rate: stats.views > 0 ? (stats.purchases / stats.views * 100) : 0
    }))
    .filter(stats => stats.views > 0); // Only include products that have been viewed
}

function getHourlyActivity() {
  // Group events by hour and event type
  const hourlyStats = {};

  for (const event of productEvents) {
    // Round down to the hour
    const hour = new Date(event.timestamp);
    hour.setMinutes(0, 0, 0);
    const hourKey = hour.toISOString();

    if (!hourlyStats[hourKey]) {
      hourlyStats[hourKey] = {};
    }

    if (!hourlyStats[hourKey][event.event_type]) {
      hourlyStats[hourKey][event.event_type] = 0;
    }

    hourlyStats[hourKey][event.event_type]++;
  }

  // Convert to array format
  const results = [];
  for (const [hour, eventTypes] of Object.entries(hourlyStats)) {
    for (const [eventType, count] of Object.entries(eventTypes)) {
      results.push({
        hour: hour,
        event_type: eventType,
        event_count: count
      });
    }
  }

  // Sort by hour descending, then by event type
  return results.sort((a, b) => {
    const hourCompare = new Date(b.hour) - new Date(a.hour);
    if (hourCompare !== 0) return hourCompare;
    return a.event_type.localeCompare(b.event_type);
  });
}

// API ENDPOINTS (equivalent to Moose consumption APIs)

app.get('/api/top-products', (req, res) => {
  try {
    const topProducts = getTopProducts();
    res.json({
      success: true,
      data: topProducts,
      count: topProducts.length,
      generated_at: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error generating top products report:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

app.get('/api/funnel', (req, res) => {
  try {
    const funnelData = getConversionFunnel();
    res.json({
      success: true,
      data: funnelData,
      count: funnelData.length,
      generated_at: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error generating funnel report:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

app.get('/api/hourly', (req, res) => {
  try {
    const hourlyData = getHourlyActivity();
    res.json({
      success: true,
      data: hourlyData,
      count: hourlyData.length,
      generated_at: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error generating hourly activity report:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'healthy',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    events_stored: productEvents.length
  });
});

// Root endpoint
app.get('/', (req, res) => {
  res.json({
    message: 'Product Analytics System',
    version: '1.0.0',
    endpoints: {
      ingestion: 'POST /ingest/ProductEvent',
      top_products: 'GET /api/top-products',
      funnel: 'GET /api/funnel',
      hourly_activity: 'GET /api/hourly',
      health: 'GET /health'
    },
    events_stored: productEvents.length
  });
});

// Start the server
app.listen(PORT, () => {
  console.log(`🚀 Product Analytics System running on port ${PORT}`);
  console.log(`📊 Ingestion endpoint: http://localhost:${PORT}/ingest/ProductEvent`);
  console.log(`📈 API endpoints:`);
  console.log(`   • Top Products: http://localhost:${PORT}/api/top-products`);
  console.log(`   • Funnel: http://localhost:${PORT}/api/funnel`);
  console.log(`   • Hourly Activity: http://localhost:${PORT}/api/hourly`);
  console.log(`🔍 Health check: http://localhost:${PORT}/health`);
});

