async function sendEventToAnalytics(event) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(event);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/ingest/ProductEvent',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      },
      rejectUnauthorized: false
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Sent event ${event.id} (${event.event_type}) for product ${event.product_id}`);
          resolve(body);
        } else {
          console.error(`✗ Failed to send event ${event.id}: ${res.statusCode} ${body}`);
          reject(new Error(`HTTP ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error(`✗ Error sending event ${event.id}:`, err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function extractAndLoad() {
  console.log('🔄 Starting Postgres extraction and loading to Analytics System...');
  console.log(`📊 Total events to process: ${mockEvents.length}`);

  let successCount = 0;
  let failureCount = 0;

  for (const event of mockEvents) {
    try {
      await sendEventToAnalytics(event);
      successCount++;
      // Small delay to avoid overwhelming the API
      await new Promise(resolve => setTimeout(resolve, 50));
    } catch (error) {
      failureCount++;
      console.error(`Failed to send event ${event.id}:`, error.message);
    }
  }

  console.log('\n📊 Extraction Summary:');
  console.log(`✅ Successfully sent: ${successCount} events`);
  console.log(`❌ Failed: ${failureCount} events`);
  console.log(`📈 Total processed: ${successCount + failureCount} events`);

  if (successCount > 0) {
    console.log('\n🎉 Data loaded successfully! You can now test the API endpoints:');
    console.log('📊 Top Products: http://localhost:3000/api/top-products');
    console.log('🔄 Conversion Funnel: http://localhost:3000/api/funnel');
    console.log('⏰ Hourly Activity: http://localhost:3000/api/hourly');
  }
}

// Run the extraction
extractAndLoad().catch(console.error);

